class Solution:
    def maxPathSum(self, root):
        best = float('-inf')
        def dfs(node):
            nonlocal best
            if not node: return 0
            left = max(0, dfs(node.left)); right = max(0, dfs(node.right))
            best = max(best, node.val + left + right)
            return node.val + max(left, right)
        dfs(root)
        return best

